mat2 rotate2D(float r){
    return mat2(cos(r), sin(r), -sin(r), cos(r));
}

mat3 rotate3D(float angle, vec3 axis){
    vec3 a = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float r = 1.0 - c;
    return mat3(
        a.x * a.x * r + c,
        a.y * a.x * r + a.z * s,
        a.z * a.x * r - a.y * s,
        a.x * a.y * r - a.z * s,
        a.y * a.y * r + c,
        a.z * a.y * r + a.x * s,
        a.x * a.z * r + a.y * s,
        a.y * a.z * r - a.x * s,
        a.z * a.z * r + c
    );
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 P,Q,o;
    P.x=iTime*0.0002;
    float i,d=1.0;
    for(;i++<2e2 && d>1e-4;
    P+=normalize(vec3((gl_FragCoord.xy*2.0-iResolution.xy)/iResolution.y,2))*rotate3D(iTime*0.2,vec3(1,2,5))*d)
    {
        Q=P;
        Q.xy=fract(Q.xy)-.5;
        for(int j;j++<8;Q+=Q)
          Q.xy=abs(Q.xy*rotate2D(Q.z+iTime*0.15))-.15; 
        d=(length(Q.xy)-0.2)/1e3; 
    }
    o+=17.10/i;
    fragColor =vec4(o,1);
}
